// Generate the archify maps that ship with the app (ADR-034, specs/010-archify-maps).
//
// For every assembly line of every `.factory/*.blueprint.json` and for each demo repo's
// fleet, write the IR JSON and the rendered self-contained HTML into `app/public/maps/`
// using the SAME `toWorkflowIR` / `toArchitectureIR` the tests validate and the VENDORED
// archify CLI — so the committed maps can never drift from the compiler (golden rule #2).
// The maps carry a `GENERATED BY GITFACTORY` header (+ blueprint hash + archify commit) and
// have the external Google Fonts link stripped so Pages serves them offline.
//
//   cd app && npm run maps          # regenerate (public/maps/ is fully owned by this script)
//   cd app && npm run maps:check    # CI: regenerate to a temp dir and diff — exit 1 on drift

import { spawnSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import {
  existsSync,
  mkdirSync,
  mkdtempSync,
  readdirSync,
  readFileSync,
  rmSync,
  writeFileSync,
} from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { blueprintHash, type Blueprint } from '../src/blueprint/types';
import { assemblyLines } from '../src/compiler/compile';
import { createDemoClient } from '../src/demo/client';
import { DEMO_REPOS } from '../src/demo/fixtures';
import { importFleet } from '../src/fleet/import';
import { parseRepo } from '../src/github/types';
import { toArchitectureIR, toWorkflowIR } from '../src/archify/ir';

const ROOT = fileURLToPath(new URL('../../', import.meta.url));
const VENDOR = join(ROOT, 'vendor/archify');
const ARCHIFY = join(VENDOR, 'bin/archify.mjs');
const OUT = join(ROOT, 'app/public/maps');
const CHECK = process.argv.includes('--check');

const archifyCommit = (() => {
  const m = /Commit\*\*: `([0-9a-f]{40})`/.exec(readFileSync(join(VENDOR, 'VENDOR.md'), 'utf8'));
  return m ? m[1].slice(0, 12) : 'unknown';
})();

interface MapJob {
  slug: string;
  type: 'workflow' | 'architecture';
  ir: unknown;
  source: string;
  hash: string;
}

function archify(args: string[]): { status: number | null; stdout: string; stderr: string } {
  const r = spawnSync(process.execPath, [ARCHIFY, ...args], { encoding: 'utf8' });
  return { status: r.status, stdout: r.stdout, stderr: r.stderr };
}

const FONT_LINK = /<link[^>]*fonts\.g(?:oogleapis|static)\.com[^>]*>\s*/g;

function renderJob(job: MapJob, dir: string) {
  const jsonPath = join(dir, `${job.slug}.${job.type}.json`);
  const htmlPath = join(dir, `${job.slug}.html`);
  writeFileSync(jsonPath, `${JSON.stringify(job.ir, null, 2)}\n`);
  const r = archify(['render', job.type, jsonPath, htmlPath, '--quality', 'showcase']);
  if (r.status !== 0)
    throw new Error(`archify render failed for ${job.slug}:\n${r.stdout}\n${r.stderr}`);
  let html = readFileSync(htmlPath, 'utf8');
  const nl = html.indexOf('\n') + 1; // keep <!DOCTYPE html> first; the header goes on line 2
  const header = `<!-- GENERATED BY GITFACTORY · ${job.type} map · source ${job.source} · hash ${job.hash} · archify ${archifyCommit} · do not edit: cd app && npm run maps -->\n`;
  html = html.slice(0, nl) + header + html.slice(nl).replace(FONT_LINK, '');
  writeFileSync(htmlPath, html);
  const c = archify(['check', htmlPath]);
  if (c.status !== 0)
    throw new Error(`archify check failed for ${job.slug}:\n${c.stdout}\n${c.stderr}`);
  const v = archify(['validate', job.type, jsonPath, '--quality', 'showcase', '--json']);
  if (v.status !== 0)
    throw new Error(`showcase validation failed for ${job.slug}:\n${v.stdout}\n${v.stderr}`);
}

async function collectJobs(): Promise<MapJob[]> {
  const jobs: MapJob[] = [];
  const factoryDir = join(ROOT, '.factory');
  for (const f of readdirSync(factoryDir)
    .filter((n) => n.endsWith('blueprint.json'))
    .sort()) {
    const rel = `.factory/${f}`;
    const bp = JSON.parse(readFileSync(join(factoryDir, f), 'utf8')) as Blueprint;
    const hash = blueprintHash(bp);
    for (const line of assemblyLines(bp)) {
      jobs.push({
        slug: line.slug,
        type: 'workflow',
        ir: toWorkflowIR(bp, line, { source: rel }),
        source: rel,
        hash,
      });
    }
  }
  // The demo fleet: a fixed clock keeps the fixture deterministic (run history is clock-relative).
  const client = createDemoClient({ clock: () => Date.parse('2026-01-01T00:00:00Z') });
  const fleets = [];
  for (const repo of DEMO_REPOS) {
    const fleet = await importFleet(client, parseRepo(repo)!);
    fleets.push(fleet);
    const ir = toArchitectureIR(fleet);
    jobs.push({
      slug: `demo--${repo.replace('/', '--')}`,
      type: 'architecture',
      ir,
      source: `demo fleet ${repo}`,
      hash: sha(ir),
    });
  }
  const all = toArchitectureIR(fleets, { title: 'Demo fleet · acme' });
  jobs.push({
    slug: 'demo--fleet',
    type: 'architecture',
    ir: all,
    source: 'demo fleet (all repos)',
    hash: sha(all),
  });
  return jobs;
}

const sha = (v: unknown) =>
  createHash('sha256').update(JSON.stringify(v)).digest('hex').slice(0, 12);

function listFiles(dir: string): string[] {
  return existsSync(dir)
    ? readdirSync(dir)
        .filter((f) => f.endsWith('.html') || f.endsWith('.json'))
        .sort()
    : [];
}

async function main() {
  const jobs = await collectJobs();
  const slugs = new Set(jobs.map((j) => j.slug));
  if (slugs.size !== jobs.length) throw new Error('duplicate map slugs');

  if (CHECK) {
    const tmp = mkdtempSync(join(tmpdir(), 'gf-maps-'));
    for (const job of jobs) renderJob(job, tmp);
    const expected = listFiles(tmp);
    const actual = listFiles(OUT);
    const drift: string[] = [];
    for (const f of new Set([...expected, ...actual])) {
      if (!expected.includes(f)) drift.push(`stale: ${f}`);
      else if (!actual.includes(f)) drift.push(`missing: ${f}`);
      else if (readFileSync(join(tmp, f), 'utf8') !== readFileSync(join(OUT, f), 'utf8'))
        drift.push(`differs: ${f}`);
    }
    rmSync(tmp, { recursive: true, force: true });
    if (drift.length) {
      console.error(`maps drift (run: cd app && npm run maps)\n  ${drift.join('\n  ')}`);
      process.exit(1);
    }
    console.log(`maps: ${expected.length} files up to date`);
    return;
  }

  mkdirSync(OUT, { recursive: true });
  for (const f of listFiles(OUT)) rmSync(join(OUT, f)); // fully owned: stale files go
  for (const job of jobs) {
    renderJob(job, OUT);
    console.log(`wrote maps/${job.slug}.html (${job.type}, ${job.source})`);
  }
  writeFileSync(
    join(OUT, 'README.md'),
    '# Generated maps\n\nEvery file here is written by `cd app && npm run maps` (ADR-034). Do not edit — change the blueprint, the fixtures, or `app/src/archify/ir.ts` and regenerate.\n',
  );
}

main().catch((err) => {
  console.error(err instanceof Error ? err.message : err);
  process.exit(1);
});
